pub struct RequestArgs {
    pub run: RunKey,
    pub verb: VerbName,
    pub over: QueryName,
    pub arguments: Option<Vec<Argument>>,
}

pub fn dispatch_request(
    repo: &mut impl crate::kernel::Repository<BulkRun>,
    route: Option<&crate::kernel::RoutingEnvelope>,
    args: RequestArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<BulkRun> {
    args.run.check_invariants()?;
    args.verb.check_invariants()?;
    args.over.check_invariants()?;
    if let Some(items) = &args.arguments {
        for item in items {
            item.check_invariants()?;
        }
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, BULK_RUN_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
            Some(__route) => {
                __route.require_depth(0)?;
                let __hydrate_id: String = args.run.value.to_string();
                if __route.aggregate() != __hydrate_id.as_str() {
                    return Err(crate::kernel::Refusal::TypeMismatch(format!(
                        "Request routes to {:?}, but its identity facts name {:?}",
                        __route.aggregate(),
                        __hydrate_id
                    )));
                }
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| BulkRun {
                        run: Some(args.run.clone()),
                        verb: Some(args.verb.clone()),
                        over: Some(args.over.clone()),
                        arguments: args.arguments.clone(),
                        results: vec![],
                        refusal: None,
                        status: "requested".to_string(),
                    }),
                    state_independent: true,
                }
            }
            None => {
                let __hydrate_id: String = args.run.value.to_string();
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| BulkRun {
                        run: Some(args.run.clone()),
                        verb: Some(args.verb.clone()),
                        over: Some(args.over.clone()),
                        arguments: args.arguments.clone(),
                        results: vec![],
                        refusal: None,
                        status: "requested".to_string(),
                    }),
                    state_independent: true,
                }
            }
        },
        "Request",
        "Bulk::BulkRun",
        "BulkRun",
        "run.value",
        &with_references,
        &[],
        None,
        |record| {
            record.run = Some(args.run.clone());
            record.verb = Some(args.verb.clone());
            record.over = Some(args.over.clone());
            record.arguments = args.arguments.clone();
            Ok(())
        },
        &[],
        &bulkrun_invariants(),
        &["BulkRunRequested"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

